#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd "${SCRIPT_DIR}/../.." && pwd)"

echo "=== Building SingTUN bridge for Android (arm64-v8a) ==="

# Find Android NDK
NDK_ROOT="${ANDROID_NDK_HOME:-${NDK_HOME:-}}"
if [[ -z "${NDK_ROOT}" ]]; then
    if [[ -n "${ANDROID_HOME:-}" && -d "${ANDROID_HOME}/ndk" ]]; then
        NDK_ROOT="$(find "${ANDROID_HOME}/ndk" -mindepth 1 -maxdepth 1 -type d | sort -V | tail -n 1)"
    elif [[ -d "${ANDROID_SDK_ROOT:-$HOME/Android/Sdk}/ndk" ]]; then
        NDK_ROOT="$(find "${ANDROID_SDK_ROOT:-$HOME/Android/Sdk}/ndk" -mindepth 1 -maxdepth 1 -type d | sort -V | tail -n 1)"
    fi
fi

if [[ -z "${NDK_ROOT}" || ! -d "${NDK_ROOT}" ]]; then
    echo "ERROR: Android NDK not found. Please set ANDROID_NDK_HOME." >&2
    exit 1
fi

echo "Using NDK: ${NDK_ROOT}"

TOOLCHAIN="${NDK_ROOT}/toolchains/llvm/prebuilt/linux-x86_64/bin"
CC_BIN="$(find "${TOOLCHAIN}" -name "aarch64-linux-android34-clang" -o -name "aarch64-linux-android*-clang" | head -n 1)"

if [[ -z "${CC_BIN}" || ! -x "${CC_BIN}" ]]; then
    echo "ERROR: aarch64 clang compiler not found in ${TOOLCHAIN}" >&2
    exit 1
fi

echo "Using Compiler: ${CC_BIN}"

cd "${SCRIPT_DIR}"

export CGO_ENABLED=1
export GOOS=android
export GOARCH=arm64
export CC="${CC_BIN}"

DEST_DIR="${ROOT_DIR}/app/src/main/jniLibs/arm64-v8a"
mkdir -p "${DEST_DIR}"

# Build directly into target directory so no duplicate .so resides in third_party
go build -buildmode=c-shared \
    -o "${DEST_DIR}/libsingtun.so" \
    -trimpath \
    -buildvcs=false \
    -ldflags="-s -w -extldflags=-Wl,-z,max-page-size=16384" \
    .

# Clean up header generated by -buildmode=c-shared in DEST_DIR if created alongside
rm -f "${DEST_DIR}/libsingtun.h" "${SCRIPT_DIR}/libsingtun.h" "${SCRIPT_DIR}/libsingtun.so"

echo "=== Successfully built and installed: ${DEST_DIR}/libsingtun.so ==="
